def capture_dependencies(requirements_path: str) -> None:
    try:
        # Use pigar to generate the list of dependencies
        subprocess.run(['pigar', '-o', requirements_path], check=True)
        logger.info(f'Dependencies captured successfully at {requirements_path}')
    except ModuleNotFoundError:
        logger.error('pigar is not installed. Please install pigar to use this function.')
        raise
    except subprocess.CalledProcessError as e:
        logger.error(f'Failed to capture dependencies: {e}')
